		public const int GOST_NUM_DENSITY = 60;

		// reference temperature

		private int ConvertTempToIndex(double temp)
		{
			int narrayypos = (int)((temp + 25.0) / .5);
			return narrayypos;
		}

		private int ConvertDensityToIndex(double density)
		{
			int narrayxpos = (int)((density * 100.0) + .5);
			narrayxpos = narrayxpos - 50;
			return narrayxpos;
		}

		public double GetDensityByTempIndexAndDensityIndex(int tempIndex, int densityIndex)
		{
			int i = tempIndex * (GOST_NUM_DENSITY + 1);
			i += densityIndex + 1;
			return this.GOST_3900_Lookup_20C_Raw_Data[i];
		}

		public double GetDensityByTempAndDensity(double temp, double density)
		{
			int densityIndex = this.ConvertDensityToIndex(density);
			int tempIndex = this.ConvertTempToIndex(temp);
         return this.GetDensityByTempIndexAndDensityIndex(tempIndex, densityIndex);
		}
	}


	public class TankVcfGOST_3900_85_20C : TankBaseVcf
	{
		public readonly GOST_3900_Lookup_20C GostTable = new GOST_3900_Lookup_20C();
      public const double GOST_INVALID_LOW = 0.001;
		public const double GOST_INVALID_HIGH = 2.001;
		

		/****************************************************************************/
		//
		// Function 		: 	CTankVcfGOST_3900_85_20C()
		//
		//	Parameters		:	None
		//
		//	Description		:	Default Constructor
		//
		//	Return Codes	:	None
		//
		/****************************************************************************/
		public TankVcfGOST_3900_85_20C()
		{
			m_byCorrectionTypeMajor = Varec.CommonComponents.VolumeCorrection.ECorrectionTypeMajor.CORR_GOST;
			m_byCorrectionTypeMinor = Varec.CommonComponents.VolumeCorrection.ECorrectionTypeMinor.CORR_3900_85_20C;
			m_bUsesDensity = false;
		}

		/****************************************************************************

			Function 		: 	TemperatureCorr()

			Parameters		:	dDensity			-> Product Density
									dMeasTemp		-> Measured Temperature
									dStdTempInC		-> Standard Temperature in Celcius
									dStdTemp			-> Standard Temperature
									bDensityUnits	-> Density Engineering Units
									bTempUnits		-> Temperature Engineering Units
									dK					-> K Factor
									pdVcfc			-> Pointer to the volume correction factor								
									Iflag				-> 0=>normal, 1=>extrap region, -1=>out of range								
									RangeCk			-> RangeCk was added to allow use with other functions 
															that calculate VCF based on density measured at the 
															observed temp. In effect, this function is placed in 
															a loop to do successive approximation.
									bRound			-> 
									bTable60			->				
									bUseDensity		->		

			Description		:	This is a wrapper function for the volume correction factor method.
									CalcTankProdVcf() makes a virtual call to this function in the 
									CTankVcfBase class.  

			Return Codes	:	true if the method executes correctly
									false if an error occurs

		/****************************************************************************/
		public override bool TemperatureCorr(double dDensity,
															  double dMeasTemp,
															  double dStdTempInC,
															  double dStdTemp,
															  EngineeringUnit bDensityUnits,
															  EngineeringUnit bTempUnits,
															  double dDensityPress,       // density pressure for api 2004
															  EngineeringUnit bDensityPressUnits, // density pressure units for api 2004
															  double dAlternateTemperature,  // selected refined product sub catagory for api 2004
															  double dBaseTemp,  // api 2004 alternate base temp reference
															  double dAlternateBasePress, // api 2004 alternate base pressure reference
															  ref double[] dK,
															  ref double pdVcfc,
															  ref int Iflag,
												ref double CTLReturn,
												ref double CPLReturn,
															  bool RangeCk,
															  bool bRound,
															  bool bTable60,           //	Optional
															  bool UseDensity)            //	Optional
		{
			bool bsuccess = false;
			double ddegc = 0.0;
			double droundtemp = 0.0;
			double dstanden = 0.0;
			double dmeasden = 0.0;

			// Set initial flag and VCF to zero.
			Iflag = 0;
			pdVcfc = 0.0;

			// Convert temperature to C
			if (!ConvertEngUnits.ConvEngrUnits(ref ddegc, dMeasTemp, EngineeringUnit.FmtDegC, bTempUnits, 0))
				return false;

			// first get the rounded temperature value to the nearest .5
			bsuccess = this.RoundDouble(ddegc, ref droundtemp, 1, false, true);

			// Set API Correction alarm below -25 C
			if (droundtemp < -25.0)
				Iflag = -1;

			if (UseDensity)
			{
				if (this.StdDensityLookup(dDensity,
											 dMeasTemp,
											 bDensityUnits,
											 bTempUnits,
											 ref dstanden))
				{
					pdVcfc = dDensity / dstanden;
				}
				else
					pdVcfc = 0.0;
			}
			else
			{
				if (this.DensityLookup(dDensity,
										 dMeasTemp,
										 bDensityUnits,
										 bTempUnits,
										 ref dmeasden))
				{
					pdVcfc = dmeasden / dDensity;
				}
				else
					pdVcfc = 0.0;
			}

			if (pdVcfc <= 0.0)
				Iflag = -1;

			return true;
		}

		/****************************************************************************

			Function 		: 	StdDensityLookup()

			Parameters		:	dMeasDensity	-> Product Density
									dMeasTemp		-> Measured Temperature
									bDensityUnits	-> Density Engineering Units
									bTempUnits		-> Temperature Engineering Units
									pdStdDensity	-> Pointer to the standard density value 
															returned								

			Description		:	This is a wrapper function for the standard density lookup.
									CalcTankStdDensity() makes a virtual call to this function in the 
									CTankVcfBase class.  

			Return Codes	:	true if the method executes correctly
									false if an error occurs

		/****************************************************************************/
		public bool StdDensityLookup(double dMeasDensity,
																		 double dMeasTemp,
																		 EngineeringUnit bDensityUnits,
																		 EngineeringUnit bTempUnits,
																		 ref double pdStdDensity)
		{
			bool bsuccess = false;
			bool breturn = false;
			double ddegc = 0.0;
			double ddenc = 0.0;
			double droundtemp = 0.0;
			double droundden = 0.0;
			double dstanden = 0.0;
			//int narrayxpos = 0, narrayypos = 0;

			// Convert temperature to C
			if (!ConvertEngUnits.ConvEngrUnits(ref ddegc, dMeasTemp, EngineeringUnit.FmtDegC, bTempUnits, 0))
				return breturn;

			// Convert density to g/cm3
			if (!ConvertEngUnits.ConvEngrUnits(ref ddenc, dMeasDensity, EngineeringUnit.FmdGcm3, bDensityUnits, 0))
				return breturn;

			// first get the rounded temperature value to the nearest .5
			bsuccess = RoundDouble(ddegc, ref droundtemp, 1, false, true);

			// next round the density to the second significant decimal
			bsuccess = RoundDouble(ddenc, ref droundden, 2, false, true);

			// 0.50 - 1.09
			if (droundden >= 0.50 &&
				 droundden <= 1.09)
			{
				// now get the std. density out of the array and do range checks
				if (droundtemp > 125)
					pdStdDensity = 0.0;
				else
				{
					// Always use the standard density @ -25.0C if below
					if (droundtemp < -25.0)
						droundtemp = -25.0;

					//narrayxpos = (int)((droundden * 100.0) + .5);
					//narrayxpos = narrayxpos - 50;

					// metric table starts at -25.0 and ends at 125 in .5 increments
					// calculate the array position
					//narrayypos = (int)((droundtemp + 25.0) / .5);

					//dstanden = GOST_3900_Lookup_20C[narrayypos].dStandardDensity[narrayxpos];
					dstanden = this.GostTable.GetDensityByTempAndDensity(droundtemp, droundden);

					// must account for invalid entries on the table
					if (GOST_INVALID_HIGH == dstanden ||
						 GOST_INVALID_LOW == dstanden)
					{
						pdStdDensity = 0.0;
						breturn = false;
					}
					else
					{
						// Add the difference of the rounding to the standard density
						if (ddenc > droundden)
							dstanden += (ddenc - droundden);
						else
							dstanden -= (droundden - ddenc);

						pdStdDensity = dstanden;
						breturn = true;
					}
				}
			}
			else
				pdStdDensity = 0.0;

			// Convert Standard Density back to user density units for the base class
			if (!ConvertEngUnits.ConvEngrUnits(ref pdStdDensity, pdStdDensity, bDensityUnits, EngineeringUnit.FmdGcm3, 0))
				breturn = false;

			if (pdStdDensity <= 0.0)
				breturn = false;

			return breturn;

		}

		/****************************************************************************

			Function 		: 	DensityLookup()

			Parameters		:	dStdDensity		-> Product Standard Density
									dMeasTemp		-> Measured Temperature
									bDensityUnits	-> Density Engineering Units
									bTempUnits		-> Temperature Engineering Units
									pdDensity		-> Pointer to the density value returned								

			Description		:	This is a wrapper function for the the density lookup.
									CalcTankDensity() makes a virtual call to this function in the 
									CTankVcfBase class.  

			Return Codes	:	true if the method executes correctly
									false if an error occurs

		/****************************************************************************/
		bool DensityLookup(double dStdDensity,
																	 double dMeasTemp,
																	 EngineeringUnit bDensityUnits,
																	 EngineeringUnit bTempUnits,
																	 ref double pdDensity)
		{
			bool bsuccess = false;
			bool breturn = false;
			double ddegc = 0.0;
			double dstddenc = 0.0;
			double droundtemp = 0.0;
			double droundstdden = 0.0;

			// Convert temperature to C
			if (!ConvertEngUnits.ConvEngrUnits(ref ddegc, dMeasTemp, EngineeringUnit.FmtDegC, bTempUnits, 0))
				return breturn;

			// Convert standard density to g/cm3
			if (!ConvertEngUnits.ConvEngrUnits(ref dstddenc, dStdDensity, EngineeringUnit.FmdGcm3, bDensityUnits, 0))
				return breturn;

			// first get the rounded temperature value to the nearest .5
			bsuccess = RoundDouble(ddegc, ref droundtemp, 1, false, true);

			// next round the density to the forth significant decimal
			bsuccess = RoundDouble(dstddenc, ref droundstdden, 4, false, true);

			// Does the density fall with the the entire table
			if (droundstdden >= 0.495 &&
				 droundstdden <= 1.1000)
			{
				// now get the density out of the array and do range checks
				if (droundtemp > 125)
					pdDensity = 0.0;
				else
				{
					int narrayxpos = 0, narrayypos = 0;
					//int nhigh = (sizeof(GOST_3900_Lookup_20C[narrayypos].dStandardDensity) / sizeof(GOST_3900_Lookup_20C[narrayypos].dStandardDensity[0] )) -1;
					int nhigh = GOST_3900_Lookup_20C.GOST_NUM_DENSITY - 1;
					//int nremainder = sizeof(GOST_3900_Lookup_20C[narrayypos].dStandardDensity ) / sizeof(GOST_3900_Lookup_20C[narrayypos].dStandardDensity[0] );
					int nremainder = GOST_3900_Lookup_20C.GOST_NUM_DENSITY;
					int nlow = 0, nmid, nhalf;
					double dlookup = 0.0;
					double ddensity = 0.0;

					// Always use the standard density @ -25.0C if below
					if (droundtemp < -25.0)
						droundtemp = -25.0;

					// metric table starts at -25.0 and ends at 125 in .5 increments
					// calculate the array position
					narrayypos = (int)((droundtemp + 25.0) / .5);

					while (nlow <= nhigh && 0.0 == ddensity)
					{
						if ((nhalf = nremainder / 2) > 0)
						{
							double dlookupprev = 0.0, dlookupnext = 0.0, ddiff = 0.0;
							int nprevpos = 0, nnextpos = 0;

							nmid = nlow + ((nremainder & 1) > 0 ? nhalf : (nhalf - 1));
							narrayxpos = nmid;

							// get the previous and next position
							nprevpos = (narrayxpos == 0) ? 0 : narrayxpos - 1;
							nnextpos = (narrayxpos == (GOST_3900_Lookup_20C.GOST_NUM_DENSITY - 1)) ? (GOST_3900_Lookup_20C.GOST_NUM_DENSITY - 1) : narrayxpos + 1;

							//dlookup = GOST_3900_Lookup_20C[narrayypos].dStandardDensity[narrayxpos];
							//dlookupprev = GOST_3900_Lookup_20C[narrayypos].dStandardDensity[nprevpos];
							//dlookupnext = GOST_3900_Lookup_20C[narrayypos].dStandardDensity[nnextpos];

							dlookup = this.GostTable.GetDensityByTempIndexAndDensityIndex(narrayypos,narrayxpos);
							dlookupprev = this.GostTable.GetDensityByTempIndexAndDensityIndex(narrayypos,nprevpos);
							dlookupnext = this.GostTable.GetDensityByTempIndexAndDensityIndex(narrayypos,nnextpos);


							if (dlookup == droundstdden)
							{
								ddensity = 0.50 + (0.01 * narrayxpos);
								breturn = true;
								break;
							}
							else if (dlookupprev >= droundstdden)     // value is on the left 
							{
								nhigh = nmid - 1;
								nremainder = (nremainder & 1) > 0 ? nhalf : nhalf - 1;
							}
							else if (dlookupnext <= droundstdden)  // value is on the right
							{
								nlow = nmid + 1;
								nremainder = nhalf;
							}
							else // value must be in-between	(IGO 04-Mar-2004)
							{
								if (dlookupprev < droundstdden &&
									 dlookup > droundstdden)
								{
									int nposition = 0;

									// Use previous element entry 
									if ((droundstdden - dlookupprev) <
										(dlookup - droundstdden))
									{
										nposition = nprevpos;
										ddiff = droundstdden - dlookupprev;
									}
									else  // use current entry
									{
										nposition = narrayxpos;
										ddiff = -1 * (dlookup - droundstdden);
									}

									ddensity = 0.50 + (0.01 * nposition);
									// Add the difference back to the density (IGO 05-Mar-2004)
									ddensity += ddiff;
									breturn = true;
								}
								// Check to see if the value falls between the current
								// and the next table value
								else if (dlookupnext > droundstdden &&
											dlookup < droundstdden)
								{
									int nposition = 0;

									// Use next element entry 
									if ((dlookupnext - droundstdden) <
										(droundstdden - dlookup))
									{
										nposition = nnextpos;
										ddiff = -1 * (dlookupnext - droundstdden);
									}
									else  // use current entry
									{
										nposition = narrayxpos;
										ddiff = droundstdden - dlookup;
									}

									ddensity = 0.50 + (0.01 * nposition);
									// Add the difference back to the density (IGO 05-Mar-2004)
									ddensity += ddiff;
									breturn = true;
								}
								else
									ddensity = 0.0;
							}
						}
						else if (nremainder > 0) // down to last element
						{
							double dlookupprev = 0.0, dlookupnext = 0.0, ddiff = 0.0;
							int nprevpos = 0, nnextpos = 0;

							narrayxpos = nlow;
							nprevpos = (narrayxpos == 0) ? 0 : narrayxpos - 1;
							nnextpos = (narrayxpos == (GOST_3900_Lookup_20C.GOST_NUM_DENSITY - 1)) ? (GOST_3900_Lookup_20C.GOST_NUM_DENSITY - 1) : narrayxpos + 1;

							//dlookup = GOST_3900_Lookup_20C[narrayypos].dStandardDensity[narrayxpos];
							//dlookupprev = GOST_3900_Lookup_20C[narrayypos].dStandardDensity[nprevpos];
							//dlookupnext = GOST_3900_Lookup_20C[narrayypos].dStandardDensity[nnextpos];
							
							dlookup =		this.GostTable.GetDensityByTempIndexAndDensityIndex(narrayypos,narrayxpos);
							dlookupprev =	this.GostTable.GetDensityByTempIndexAndDensityIndex(narrayypos,nprevpos);
							dlookupnext =	this.GostTable.GetDensityByTempIndexAndDensityIndex(narrayypos,nnextpos);

							if (dlookup == droundstdden)
							{
								ddensity = 0.50 + (0.01 * narrayxpos);
								breturn = true;
							}
							// Check to see if the value falls between the current
							// and the previous table value
							else if (dlookupprev < droundstdden &&
										dlookup > droundstdden)
							{
								int nposition = 0;

								// Use previous element entry 
								if ((droundstdden - dlookupprev) <
									(dlookup - droundstdden))
								{
									nposition = nprevpos;
									ddiff = droundstdden - dlookupprev;
								}
								else  // use current entry
								{
									nposition = narrayxpos;
									ddiff = -1 * (dlookup - droundstdden);
								}

								ddensity = 0.50 + (0.01 * nposition);
								// Add the difference back to the density (IGO 05-Mar-2004)
								ddensity += ddiff;
								breturn = true;
							}
							// Check to see if the value falls between the current
							// and the next table value
							else if (dlookupnext > droundstdden &&
										dlookup < droundstdden)
							{
								int nposition = 0;

								// Use next element entry 
								if ((dlookupnext - droundstdden) <
									(droundstdden - dlookup))
								{
									nposition = nnextpos;
									ddiff = -1 * (dlookupnext - droundstdden);
								}
								else  // use current entry
								{
									nposition = narrayxpos;
									ddiff = droundstdden - dlookup;
								}

								ddensity = 0.50 + (0.01 * nposition);
								// Add the difference back to the density (IGO 05-Mar-2004)
								ddensity += ddiff;
								breturn = true;
							}
							else
								ddensity = 0.0;
							break;
						}
						else
							break;
					}

					pdDensity = ddensity;
				}
			}
			else
				pdDensity = 0.0;

			// Convert Density back to user density units for the base class
			if (!ConvertEngUnits.ConvEngrUnits(ref pdDensity, pdDensity, bDensityUnits, EngineeringUnit.FmdGcm3, 0))
				breturn = false;

			if (pdDensity <= 0.0)
				breturn = false;

			return breturn;
		}

	}
}
